changeSet.sql:
/* ----------------------------------------------------- Permission | Old Value | New Value | ----------------------------------------------------- ReadAsset | 1 | 1 | AddAsset | - | 2 | DeleteAsset | 4 | 4 | EditAsset | - | 8 | ModifyAsset | 2 | 2|8 |
ReadResponsibilities | 64 | 32 | AddResponsibilities | - | 64 | DeleteResponsibilities | 256 | 128 | EditResponsibilities | - | 256 | ModifyResponsibilities | 128 | 64|256 |
ReadRelationship | 512 | 1024 | AddRelationship | - | 2048 | DeleteRelationship | 2048 | 4096 | EditRelationship | - | 8192 | ModifyRelationship | 1024 | 2048|8192 | ----------------------------------------------------- */
--clear old Attribute flags from last year 8,16,32 update R set R.PermissionsBitMask = R.PermissionsBitMask ^ 8 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 8 = 8;
update R set R.PermissionsBitMask = R.PermissionsBitMask ^ 16 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 16 = 16;
update R set R.PermissionsBitMask = R.PermissionsBitMask ^ 32 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 32 = 32;
--update ModifyAsset to AddAsset|EditAsset update R set R.PermissionsBitMask = R.PermissionsBitMask | 8 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 2 = 2;
--update ReadResponsibilities to 32 update R set R.PermissionsBitMask = R.PermissionsBitMask | 32 ^ 64 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 64 = 64;
--store DeleteResponsibilities in 16 update R set R.PermissionsBitMask = R.PermissionsBitMask | 16 ^ 256 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 256 = 256;
--update ModifyResponsibilities(128) to AddResponsibilities|EditResponsibilities update R set R.PermissionsBitMask = R.PermissionsBitMask | 64 | 256 ^ 128 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 128 = 128;
--restore 16 to new DeleteResponsibilities(128) update R set R.PermissionsBitMask = R.PermissionsBitMask | 128 ^ 16 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 16 = 16;
--store ReadRelationships(512) in 16 update R set R.PermissionsBitMask = R.PermissionsBitMask | 16 ^ 512 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 512 = 512;
--update DeleteRelationship to 4096 update R set R.PermissionsBitMask = R.PermissionsBitMask | 4096 ^ 2048 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 2048 = 2048;
--update ModifyRelationship to AddRelationship|EditRelationship update R set R.PermissionsBitMask = R.PermissionsBitMask | 2048 | 8192 ^ 1024 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 1024 = 1024;
--restore 16 to ReadRelationship(1024) update R set R.PermissionsBitMask = R.PermissionsBitMask | 1024 ^ 16 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 16 = 16;

changeSet.rollback:
--store ModifyRelationship in 16 update R set R.PermissionsBitMask = R.PermissionsBitMask | 16 ^ (2048|8192) from ResponsibilityTypeRelation R where R.PermissionsBitMask & (2048|8192) = (2048|8192);
--revert DeleteRelationship update R set R.PermissionsBitMask = R.PermissionsBitMask | 2048 ^ 4096 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 4096 = 4096;
--revert ReadRelationship update R set R.PermissionsBitMask = R.PermissionsBitMask | 512 ^ 1024 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 1024 = 1024;
--restore ModifyRelationship update R set R.PermissionsBitMask = R.PermissionsBitMask | 1024 ^ 16 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 16 = 16;
--store ModifyResponsibilities in 16 update R set R.PermissionsBitMask = R.PermissionsBitMask | 16 ^ (64|256) from ResponsibilityTypeRelation R where R.PermissionsBitMask & (64|256) = (64|256);
--revert DeleteResponsibilities update R set R.PermissionsBitMask = R.PermissionsBitMask | 256 ^ 128 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 128 = 128;
--revert ReadResponsibilities update R set R.PermissionsBitMask = R.PermissionsBitMask | 64 ^ 32 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 32 = 32;
--restore ModifyResponsibilities update R set R.PermissionsBitMask = R.PermissionsBitMask | 128 ^ 16 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 16 = 16;
--clear EditAsset bit update R set R.PermissionsBitMask = R.PermissionsBitMask ^ 8 from ResponsibilityTypeRelation R where R.PermissionsBitMask & 8 = 8;

changeSet.sql:
set nocount on;
IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = 'dbo' AND TABLE_NAME = 'FieldTypeLookup_Backup') BEGIN CREATE TABLE [dbo].[FieldTypeLookup_Backup]( [FieldTypeID] [int] NOT NULL, [Definition] [nvarchar](max) NOT NULL ) END
declare @fieldTypes table (RowNumber int identity, FieldTypeID int, Definition nvarchar(max)) insert into @fieldTypes select F.ID, L.Definition from FieldType F inner join FieldTypeLookup L on L.FieldTypeID = F.ID and F.Type = 'ComplexRelationLookup';
-- Backup in case anything gets totally hosed. if not exists (select 1 from FieldTypeLookup_Backup) BEGIN insert into FieldTypeLookup_Backup select FieldTypeID, Definition from @fieldTypes END
declare @current int = 1, @max int
select @max = max(RowNumber) from @fieldTypes
declare @relations table ( MasterFieldTypeID int, RowOrder int, IntersectTypeUid uniqueidentifier, IntersectTypeID int, AssetTypeUid uniqueidentifier, Object varchar(50), ObjectID int, RelationType int, Direction int )
declare @fields table ( MasterFieldTypeID int, AssetTypeUid uniqueidentifier, Object varchar(50), ObjectID int, FieldTypeID int, FieldTypeName nvarchar(250), [Filter] nvarchar(max), OverrideDisplayName nvarchar(250), DisplayOrder int, SortOrder int, Show bit, Width int )
while @current <= @max begin declare @json nvarchar(2500), @id int select @id = FieldTypeID, @json = Definition from @fieldTypes where RowNumber = @current;
declare @temp_relations table ( RowOrder int identity, IntersectTypeUid uniqueidentifier, IntersectTypeID int, AssetTypeUid uniqueidentifier, Object varchar(50), ObjectID int, RelationType int, Direction int);
begin try insert into @temp_relations select * from OPENJSON(@json, N'lax $.Relations') with ( IntersectTypeUid uniqueidentifier, IntersectTypeID int, AssetTypeUid uniqueidentifier, Object varchar(50), ObjectID int, RelationType int, Direction int );
insert into @relations select @id, * from @temp_relations
delete @temp_relations
insert into @fields select @id, * from OPENJSON(@json, N'lax $.Fields') with ( AssetTypeUid uniqueidentifier, Object varchar(50), ObjectID int, FieldTypeID int, FieldTypeName nvarchar(250), [Filter] nvarchar(max), OverrideDisplayName nvarchar(250), DisplayOrder int, SortOrder int, Show bit, Width int )
delete @fieldTypes where RowNumber = @current end try begin catch
end catch
set @current = @current+1 end
update R set R.IntersectTypeID = T.ID from @relations R inner join IntersectTypeDetail T on R.RelationType = 3 and T.Object = R.Object and T.ObjectID = R.ObjectID and T.PredicateType in (3,4) and R.IntersectTypeID = 0
update R set R.IntersectTypeID = T.ID from @relations R inner join IntersectTypeDetail T on R.RelationType = 4 and T.Subject = R.Object and T.SubjectID = R.ObjectID and T.PredicateType in (3,4) and R.IntersectTypeID = 0
update R set R.IntersectTypeUid = I.Uid from @relations R inner join IntersectType I on I.ID = R.IntersectTypeID;
update R set R.AssetTypeUid = A.Uid from @relations R inner join AssetType A on A.Object = R.Object and A.ObjectID = R.ObjectID;
update R set R.AssetTypeUid = A.Uid from @fields R inner join AssetType A on A.Object = R.Object and A.ObjectID = R.ObjectID;
update R set R.Direction = case when A.Object = I.Object and A.ObjectID = I.ObjectID then 2 when A.Object = I.Subject and A.ObjectID = I.SubjectID then 1 else R.Direction end from @relations R inner join IntersectType I on I.Uid = R.IntersectTypeUid and R.RelationType = 1 inner join AssetType A on A.Uid = R.AssetTypeUid;
update @relations set Direction = case RelationType when 3 then 2 when 4 then 1 else Direction end where RelationType in (3,4);
update T set T.[Definition] = S.[Definition] from FieldTypeLookup T inner join ( select MasterFieldTypeID as FieldTypeID, ( select ( select IntersectTypeUid, AssetTypeUid, RelationType, Direction from @relations where MasterFieldTypeID = R.MasterFieldTypeID order by RowOrder for json path ) as Relations, ( select AssetTypeUid, FieldTypeID, FieldTypeName, [Filter], OverrideDisplayName, DisplayOrder, SortOrder, Show, Width from @fields where MasterFieldTypeID = R.MasterFieldTypeID for json path ) as Fields for json path, WITHOUT_ARRAY_WRAPPER ) as [Definition] from @relations R group by R.MasterFieldTypeID ) S on S.FieldTypeID = T.FieldTypeID and S.Definition is not null


DECLARE @ObjectID INT;
DECLARE @ResourceID INT;

DECLARE cursorDelete CURSOR
LOCAL STATIC
FOR
SELECT ot.ID AS ObjectID, ISNULL(ot.UpdatedBy, 0) as RecsourceID
FROM [dbo].[OrganizationType] ot
INNER JOIN [dbo].[AssetType] at ON at.[Object] = 'OrganizationType' AND at.ObjectID = ot.ID
WHERE ot.[State] = 3;

OPEN cursorDelete;

FETCH NEXT FROM cursorDelete INTO @ObjectID, @ResourceID;
WHILE @@FETCH_STATUS = 0
BEGIN
	EXEC [dbo].[DeleteObject] 'OrganizationType', @ObjectID, @ResourceID;
    FETCH NEXT FROM cursorDelete INTO @ObjectID, @ResourceID;
END;
CLOSE cursorDelete; 
DEALLOCATE cursorDelete;

update V set V.EffectiveEndDate = DATEADD(dd, -1, NV.EffectiveDate) from metrics.AssetVersion V cross apply ( select min(EffectiveDate) as EffectiveDate from metrics.AssetVersion where AssetUid = V.AssetUid and EffectiveDate > V.EffectiveDate ) NV where V.EffectiveEndDate is null;
update V set V.EffectiveEndDate = DATEADD(dd, -1, NV.EffectiveDate) from metrics.AssetVersion V cross apply ( select min(EffectiveDate) as EffectiveDate from metrics.AssetVersion where AssetUid = V.AssetUid and EffectiveDate > V.EffectiveDate ) NV where NV.EffectiveDate = V.EffectiveEndDate;
update V set V.EffectiveEndDate = DATEADD(dd, -1, NV.EffectiveDate) from metrics.AssetVersion V cross apply ( select min(EffectiveDate) as EffectiveDate from metrics.AssetVersion where AssetUid = V.AssetUid and EffectiveDate > V.EffectiveDate ) NV where NV.EffectiveDate < V.EffectiveEndDate;


update metrics.AssetVersion set Definition = replace(Definition, '"Check":0', '"Check":"External"') where Definition like '%"Check":0%';

update metrics.AssetVersion set Definition = '{"DataQuality":null,"Governance":{"Check":"External","Field":null,"Predicate":null,"Relation":null,"Owner":null,"External":{"UpdateFrequency":0,"Instructions":null}}}' 
where Definition = '{ "Check": "External" }' or Definition = '{ "Check": "External"}'; 

update metrics.AssetVersion set Definition ='{}' where Definition = 'null' or Definition is null;

delete T from CommentVote T inner join Comment C on C.ID = T.CommentID and C.CommentType not in (1,2,5);
delete T from CommentRelation T inner join Comment C on C.ID = T.CommentID and C.CommentType not in (1,2,5);
delete Comment where CommentType not in (1,2,5);

--Governance -- Update root. update I set I.DisplayWeight = case when floor(I.DecimalValue) = FLOOR(I.AdjustedWeight) then cast(I.DecimalValue as decimal(8,6)) else cast((I.DecimalValue*I.AdjustedMaxWeight) as decimal(8,6)) end, I.DisplayMaxWeight = cast(I.AdjustedMaxWeight as decimal(8,6)) from metrics.ScoreItem I inner join metrics.AssetVersion V on V.Uid = I.AssetVersionUid --and I.DisplayWeight is null inner join metrics.Asset A on A.Uid = V.AssetUid and A.ParentUid is null inner join metrics.Allocation L on L.Uid = A.AllocationUid and L.ScoreType = 1 inner join metrics.ScoreItemLink J on J.ScoreItemUid = I.Uid;
-- Update children. update I set I.DisplayWeight = cast((I.AdjustedWeight*[PI].AdjustedMaxWeight) as decimal(8,6)), I.DisplayMaxWeight = cast((I.AdjustedMaxWeight*[PI].AdjustedMaxWeight) as decimal(8,6)) from metrics.ScoreItem I inner join metrics.AssetVersion V on V.Uid = I.AssetVersionUid and I.DisplayWeight is null inner join metrics.Asset A on A.Uid = V.AssetUid and A.ParentUid is not null inner join metrics.Allocation L on L.Uid = A.AllocationUid and L.ScoreType = 1 inner join metrics.ScoreItemLink J on J.ScoreItemUid = I.Uid inner join metrics.Asset PA on PA.Uid = A.ParentUid inner join metrics.AssetVersion PV on PV.AssetUid = PA.Uid inner join metrics.ScoreItemLink PJ on PJ.ScoreUid = J.ScoreUid inner join metrics.ScoreItem [PI] on [PI].Uid = PJ.ScoreItemUid and [PI].AssetVersionUid = PV.Uid;
-- Data Quality -- Update root. update I set I.DisplayWeight = cast(I.AdjustedWeight as decimal(8,6)), I.DisplayMaxWeight = cast(I.AdjustedMaxWeight as decimal(8,6)) from metrics.ScoreItem I inner join metrics.AssetVersion V on V.Uid = I.AssetVersionUid and I.DisplayWeight is null inner join metrics.Asset A on A.Uid = V.AssetUid and A.ParentUid is null inner join metrics.Allocation L on L.Uid = A.AllocationUid and L.ScoreType = 2 inner join metrics.ScoreItemLink J on J.ScoreItemUid = I.Uid ;
-- Update children. update I set I.DisplayWeight = cast((I.AdjustedWeight*[PI].AdjustedMaxWeight) as decimal(8,6)), I.DisplayMaxWeight = cast((I.AdjustedMaxWeight*[PI].AdjustedMaxWeight) as decimal(8,6)) from metrics.ScoreItem I inner join metrics.AssetVersion V on V.Uid = I.AssetVersionUid and I.DisplayWeight is null inner join metrics.Asset A on A.Uid = V.AssetUid and A.ParentUid is not null inner join metrics.Allocation L on L.Uid = A.AllocationUid and L.ScoreType = 2 inner join metrics.ScoreItemLink J on J.ScoreItemUid = I.Uid inner join metrics.Asset PA on PA.Uid = A.ParentUid inner join metrics.AssetVersion PV on PV.AssetUid = PA.Uid inner join metrics.ScoreItemLink PJ on PJ.ScoreUid = J.ScoreUid inner join metrics.ScoreItem [PI] on [PI].Uid = PJ.ScoreItemUid and [PI].AssetVersionUid = PV.Uid

		Queue Elasticsearch rebuild after adding AssetPath to index.

INSERT INTO [queue].[task] (Action, Custom, Date, Object, ObjectID)
SELECT 'QueueRebuild', 'SearchIndex', DATEADD(HOUR, 1, getdate()), 'Queue', 0;

Queue Elasticsearch index of Semantics, delayed 1 hour to allow for code deployment.

INSERT INTO [queue].[task] (Action, Custom, Date, Object, ObjectID)
SELECT 'QueueRebuild', 'SearchIndex', DATEADD(HOUR, 1, getdate()), 'SemanticType', 0;


Declare @ID int = (select ID from sitenav where name = '#Fusion' and parentID is null);

if (@ID is not null)
begin
	delete from SiteNavPermission where SiteNavID = @ID;

	delete from sitenav where ID = @ID;
end


declare @totalcount bigint = 0,
		@runcount bigint = 0,
		@fieldtypeid int;

drop table if exists #tempfieldid;

create table #tempfieldid (id [bigint] IDENTITY(1,1) NOT NULL, FieldTypeId [bigint]);

insert into #tempfieldid (FieldTypeId)
select ft.id
from fieldtype ft
where object = 'IssueType'
and not exists (select 1 
				from IssueType it 
				where it.id = ft.ObjectID
				);

create nonclustered index cix_tempfieldid1 on #tempfieldid (id);
create nonclustered index cix_tempfieldid2 on #tempfieldid (FieldTypeid);

select @totalcount = count(id) from #tempfieldid;

while (@runcount <= @totalcount)
begin
	set @runcount = @runcount + 1;

	set @fieldtypeid = null;

	select @fieldtypeid = tf.fieldtypeid 
	from #tempfieldid tf
	where id = @runcount
	and exists (select 1 from field f
				where f.fieldtypeid = tf.fieldtypeid);

	if (@fieldtypeid is not null)
	begin
		delete  f
		from    Field f
		where   f.fieldtypeid = @fieldtypeid;
	end
end;

delete	FT
from	dbo.FieldType FT
inner join #tempfieldid T on T.FieldTypeID = FT.ID
where FT.object = 'IssueType';

drop table if exists #tempfieldid;


declare @totalcount bigint = 0,
		@runcount bigint = 0,
		@fieldtypeid int;

drop table if exists #tempMissingIssueData;
drop table if exists #tempfieldid;

create table #tempfieldid (id [bigint] IDENTITY(1,1) NOT NULL, FieldTypeId [bigint]);

select F.FieldTypeID,F.ID
into #tempMissingIssueData
from Field F
where F.objectType = 'Issue' 
and not exists (select 1 from issue s where s.id = f.objectid);

create nonclustered index cix_tempMissingIssueData on #tempMissingIssueData(FieldTypeID,ID);


insert into #tempfieldid (FieldTypeId)
select Distinct f.FieldTypeID
from #tempMissingIssueData f;

create nonclustered index cix_tempfieldid1 on #tempfieldid (id);
create nonclustered index cix_tempfieldid2 on #tempfieldid (FieldTypeid);

select @totalcount = count(id) from #tempfieldid;

while (@runcount <= @totalcount)
begin
	set @runcount = @runcount + 1;

	set @fieldtypeid = null;

	select @fieldtypeid = tf.fieldtypeid 
	from #tempfieldid tf
	where id = @runcount;

	if (@fieldtypeid is not null)
	begin
		delete  f
		from    Field f
		inner join #tempMissingIssueData s on s.id = f.id and s.fieldtypeid = f.fieldtypeid
		where   f.fieldtypeid = @fieldtypeid;
	end
end

drop table if exists #tempMissingIssueData;
drop table if exists #tempfieldid;


declare @totalcount bigint = 0,
		@runcount bigint = 0,
		@fieldtypeid int;

drop table if exists #tempfieldid;

create table #tempfieldid (FieldTypeId [bigint]);

insert into #tempfieldid (FieldTypeId)
select ft.id
from fieldtype ft
where ft.object = 'IntersectType'
and not exists (select 1 
				from IntersectType it 
				where it.id = ft.ObjectID
				);

create nonclustered index cix_tempfieldid2 on #tempfieldid (FieldTypeid);

delete  f
from    Field f
inner join #tempfieldid t on f.fieldtypeid = t.fieldtypeid;

delete	FT
from	dbo.FieldType FT
inner join #tempfieldid T on T.FieldTypeID = FT.ID;

drop table if exists #tempfieldid;

DISABLE TRIGGER ALL ON [dbo].[Intersect];
update T set T.SubjectAssetID = S.ID, T.SubjectAssetTypeID = S.AssetTypeID from [Intersect] T inner join Asset S on S.Object = T.Subject and S.ObjectId = T.SubjectID where T.SubjectAssetID is null;
update T set T.ObjectAssetID = S.ID, T.ObjectAssetTypeID = S.AssetTypeID from [Intersect] T inner join Asset S on S.Object = T.Object and S.ObjectId = T.ObjectID where T.ObjectAssetID is null;
update T set T.ObjectAssetID = 0, T.ObjectAssetTypeID = S.ID from [Intersect] T inner join AssetType S on S.Object = T.Object and S.ObjectId = T.ObjectID where T.ObjectAssetID is null;
ENABLE TRIGGER ALL ON [dbo].[Intersect];


DISABLE TRIGGER ALL ON [dbo].[Intersect];

update	T
set		T.SubjectAssetID = 0,
		T.SubjectAssetTypeID = S.ID
from	[Intersect] T inner join AssetType S on S.Object = T.Subject and S.ObjectId = T.SubjectID
where	T.SubjectAssetID is null;

ENABLE TRIGGER ALL ON [dbo].[Intersect];


IF (OBJECT_ID('DF_Report_ReportType') IS NOT NULL)
begin
		ALTER TABLE [dbo].[Report] DROP CONSTRAINT DF_Report_ReportType;
		ALTER TABLE [dbo].[Report] ALTER COLUMN ReportType [int];
end

update F set F.AssetID = A.ID from Follow F inner join Asset A on A.Object = F.ObjectType and A.ObjectId = F.ObjectId where F.FollowTypeID = 1 and F.AssetID is null and F.AssetTypeID is null;
update F set F.AssetTypeID = ATT.ID from Follow F inner join AssetType ATT on ATT.Object = F.ObjectType and ATT.ObjectId = F.ObjectId where F.FollowTypeID = 3 and F.ObjectType in ('ArtifactType','ReferenceItemType','PolicyType','TaxonomyType','RuleType') and F.AssetID is null and F.AssetTypeID is null;
update F set F.AssetTypeID = (select top 1 ATT.ID from AssetType ATT where ATT.object = 'GroupType') from Follow F where F.ObjectType = 'Group' and F.ObjectID = 0 and F.FollowTypeID = 3 and F.AssetID is null and F.AssetTypeID is null;
update F set F.AssetTypeID = (select top 1 ATT.ID from AssetType ATT where ATT.object = 'ResourceType') from Follow F where F.ObjectType = 'ResourceType' and F.FollowTypeID = 3 and F.AssetID is null and F.AssetTypeID is null;
update F set F.AssetID = A.ID from Follow F inner join Asset A on A.Object = F.ObjectType and A.ObjectId = F.ObjectId where F.FollowTypeID = 3 and F.ObjectType in ('Policy','Taxonomy') and F.AssetID is null and F.AssetTypeID is null;
if exists(select 1 from Follow F where F.AssetID is null and F.AssetTypeID is null) begin update F set F.AssetID = A.ID from Follow F inner join Asset A on A.Object = F.ObjectType and A.ObjectId = F.ObjectId where F.AssetID is null and F.AssetTypeID is null;
update F set F.AssetTypeID = ATT.ID from Follow F inner join AssetType ATT on ATT.Object = F.ObjectType and ATT.ObjectId = F.ObjectId where F.AssetID is null and F.AssetTypeID is null; end

begin
declare @iteration int, @itearationMax int;
set @iteration = 0; select @itearationMax = max(cnt) from ( select ( select count(*) from OPENJSON(rtrr.definition, '$.When') with ( FieldTypeid int '$.FieldTypeID', Value NVARCHAR(max) '$.Value' ) as summary inner join FieldType ft on ft.id = summary.FieldTypeid where ft.Type = 'Lookup' and isnumeric(summary.value) <> 1 ) as cnt from ResponsibilityTypeRelationRule rtrr ) cntSel;
While (@iteration < @itearationMax) begin update rtrr set rtrr.Definition = JSON_MODIFY(rtrr.definition, concat('$.When[', j1.[key], '].Value') COLLATE SQL_Latin1_General_CP1_CI_AS, flv.value) ,rtrr.UpdatedOn = getdate() from ResponsibilityTypeRelationRule as rtrr cross apply OPENJSON(rtrr.definition, '$.When') j1 cross apply OPENJSON(j1.[value], '$') with ( FieldTypeid int '$.FieldTypeID', Value NVARCHAR(max) '$.Value' ) as summary inner join FieldType ft on ft.id = summary.FieldTypeid cross apply (select top 1 value from FieldLookupValue flv where flv.FieldTypeID = ft.id and summary.value = flv.text)flv(value) where ft.Type = 'Lookup' and isnumeric(summary.value) <> 1;
set @iteration = @iteration+1; end;
set @iteration = 0; select @itearationMax = max(cnt) from ( select ( select count(*) from OPENJSON(rtrr.definition, '$.Then.Conditions') with ( FieldTypeid int '$.FieldTypeID', Value NVARCHAR(max) '$.Value' ) as summary inner join FieldType ft on ft.id = summary.FieldTypeid where ft.Type = 'Lookup' and isnumeric(summary.value) <> 1 ) as cnt from ResponsibilityTypeRelationRule rtrr ) cntSel;
While (@iteration < @itearationMax) begin update rtrr set rtrr.Definition = JSON_MODIFY(rtrr.definition, concat('$.Then.Conditions[', j1.[key], '].Value') COLLATE SQL_Latin1_General_CP1_CI_AS, flv.value) ,rtrr.UpdatedOn = getdate() from ResponsibilityTypeRelationRule as rtrr cross apply OPENJSON(rtrr.definition, '$.Then.Conditions') j1 cross apply OPENJSON(j1.[value], '$') with ( FieldTypeid int '$.FieldTypeID', Value NVARCHAR(max) '$.Value' ) as summary inner join FieldType ft on ft.id = summary.FieldTypeid cross apply (select top 1 value from FieldLookupValue flv where flv.FieldTypeID = ft.id and summary.value = flv.text)flv(value) where ft.Type = 'Lookup' and isnumeric(summary.value) <> 1;
set @iteration = @iteration+1; end;
end
